import { Link, useLocation, useParams } from "wouter";
import { useQueryClient } from "@tanstack/react-query";
import { ArrowDownLeft, ArrowUpLeft, Check, ChevronLeft, CircleAlert, CircleDollarSign, Download, Edit3, Filter, Package, Plus, Receipt, ShoppingCart, Trash2, TrendingUp, Truck, UserRound, WalletCards } from "lucide-react";
import {
  getExportReportQueryKey, getGetCustomerQueryKey, getGetDashboardQueryKey, getGetOrderQueryKey, getGetReportSummaryQueryKey, getGetSettingsQueryKey, getGetWalletQueryKey, getListAuditLogsQueryKey, getListCustomersQueryKey, getListOrdersQueryKey, getListPaymentsQueryKey, getListPurchasesQueryKey, getListShipmentsQueryKey,
  useCreateCustomer, useCreateOrder, useCreatePayment, useCreatePurchase, useCreateShipment, useCreateWalletAdjustment, useCreateWalletTransaction, useDeletePayment, useDeletePurchase, useDeleteShipment, useDeleteWalletTransaction, useGetCustomer, useGetDashboard, useGetOrder, useGetReportSummary, useGetSettings, useGetWallet, useListAuditLogs, useListCustomers, useListOrders, useListPayments, useListPurchases, useListShipments, useUpdateCustomer, useUpdateOrderItem, useUpdatePayment, useUpdatePurchase, useUpdateSettings, useUpdateShipment, useUpdateWalletTransaction, useExportReport, type Payment, type SheinPurchase, type Shipment, type WalletTransaction
} from "@workspace/api-client-react";
import { AppShell } from "@/components/app-shell";
import { AccountManagement } from "@/components/account-management";
import { Button, EmptyState, Input, Money, Modal, PageHeader, PageSkeleton, QueryState, SearchBox, Select, Spinner, Status, Textarea, Toast, UploadField } from "@/components/primitives";

const today = new Date().toISOString().slice(0, 10);
const fmtDate = (value?: string | null) => value ? new Date(value).toLocaleDateString("ar-IL", { day: "numeric", month: "short", year: "numeric" }) : "—";
const safeArray = <T,>(value?: T[]) => value || [];

function Flash({ message, error = false }: { message: string; error?: boolean }) { return <Toast message={message} type={error ? "error" : "success"}/>; }
function useFlash() {
  const [flash, setFlash] = useState<{ message: string; error?: boolean } | null>(null);
  const notify = (message: string, error = false) => {
    setFlash({ message, error });
    window.setTimeout(() => setFlash(null), 2500);
  };
  return { flash, notify };
}
function ConfirmModal({ open, title, description, pending, onClose, onConfirm }: { open: boolean; title: string; description: string; pending?: boolean; onClose: () => void; onConfirm: () => void }) {
  return <Modal open={open} onClose={onClose} title={title}><p className="text-sm leading-7 text-muted-foreground">{description}</p><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onClose} disabled={pending}>إلغاء</Button><Button type="button" variant="danger" onClick={onConfirm} disabled={pending}>{pending && <Spinner/>} نعم، حذف</Button></div></Modal>;
}
function isManualExpense(transaction: WalletTransaction) {
  return transaction.type === "expense"
    && !transaction.relatedPaymentId
    && !transaction.relatedPurchaseId
    && !transaction.relatedShipmentId
    && !transaction.relatedOrderId
    && !transaction.relatedCustomerId;
}
function StatCard({ label, value, sub, icon: Icon, tone = "primary" }: { label: string; value: ReactNode; sub?: string; icon: typeof WalletCards; tone?: "primary" | "gold" | "coral" | "mint" }) {
  const tones = { primary: "bg-primary text-primary-foreground", gold: "bg-secondary text-secondary-foreground", coral: "bg-accent text-accent-foreground", mint: "bg-[#dce9df] text-[#1d5945]" };
  return <div className={`animate-rise rounded-2xl p-5 shadow-sm ${tones[tone]}`} data-testid={`card-stat-${label}`}>
    <div className="mb-6 flex items-start justify-between"><span className="text-xs font-semibold opacity-75">{label}</span><span className="grid size-9 place-items-center rounded-xl bg-black/10"><Icon size={18}/></span></div>
    <div className="font-display text-2xl font-bold tabular-nums" data-testid={`text-stat-${label}`} dir="ltr">{value}</div>
    {sub && <p className="mt-1 text-[11px] opacity-70">{sub}</p>}
  </div>;
}
function SectionCard({ title, action, children, className = "" }: { title: string; action?: ReactNode; children: ReactNode; className?: string }) { return <section className={`rounded-2xl border border-card-border bg-card shadow-[0_8px_26px_rgba(32,60,61,.04)] ${className}`}><div className="flex items-center justify-between border-b border-border/70 px-5 py-4"><h3 className="font-display font-bold">{title}</h3>{action}</div>{children}</section>; }
function AppPage({ children }: { children: ReactNode }) { return <AppShell>{children}</AppShell>; }

export function DashboardPage() {
  const q = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const d = q.data;
  if (q.isLoading) return <AppPage><PageSkeleton/></AppPage>;
  if (q.isError || !d) return <AppPage><QueryState isError onRetry={() => { void q.refetch(); }}/></AppPage>;
  return <AppPage><div className="soft-grid -mx-4 -mt-6 px-4 pb-8 pt-6 sm:-mx-7 sm:px-7 sm:pt-8">
    <PageHeader eyebrow="ملخص اليوم · ١٥ أكتوبر" title="لوحة القيادة" description="صورة واضحة لحركة الطلبات، البضاعة، والسيولة — بدون تخمين." action={<Link href="/orders/new" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground shadow-sm transition-transform hover:-translate-y-0.5" data-testid="link-dashboard-new-order"><Plus size={17}/> تسجيل طلب</Link>}/>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <StatCard label="رصيد المحفظة" value={<Money value={d.walletBalance}/>} sub="السيولة المتاحة الآن" icon={WalletCards} tone="primary"/>
      <StatCard label="مستحق من العملاء" value={<Money value={d.customerOwed}/>} sub="إجمالي الأرصدة المتبقية" icon={ArrowDownLeft} tone="gold"/>
      <StatCard label="طلبات نشطة" value={d.activeOrders} sub={`${d.waitingProducts} منتج بانتظار الوصول`} icon={ShoppingCart} tone="coral"/>
      <StatCard label="الربح التقديري" value={<Money value={d.estimatedProfit}/>} sub={`عمولة مسجلة ${new Intl.NumberFormat("ar-IL").format(d.commission)} ₪`} icon={TrendingUp} tone="mint"/>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_.8fr]">
      <SectionCard title="طلبات تحتاج انتباهك" action={<Link href="/orders" className="text-xs font-bold text-primary hover:underline" data-testid="link-dashboard-orders">كل الطلبات</Link>}>
        <div className="divide-y divide-border/70">{safeArray(d.recentOrders).slice(0, 5).map((o) => <Link href={`/orders/${o.id}`} key={o.id} className="flex items-center gap-3 px-5 py-4 transition-colors hover:bg-muted/50" data-testid={`link-dashboard-order-${o.id}`}><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-secondary/20 text-primary"><Package size={18}/></span><span className="min-w-0 flex-1"><span className="flex items-center gap-2"><strong className="text-sm">{o.orderNumber}</strong><Status value={o.status}/></span><small className="mt-1 block truncate text-xs text-muted-foreground">{o.customerName} · {o.itemCount} منتجات</small></span><span className="text-left"><Money value={o.totalSelling} className="text-sm font-bold"/><small className="mt-1 block text-[10px] text-muted-foreground">السعر المحصل</small></span><ChevronLeft size={15} className="text-muted-foreground"/></Link>)}</div>
        {safeArray(d.recentOrders).length === 0 && <EmptyState title="لا توجد طلبات حديثة" description="عندما تسجل طلباً جديداً سيظهر هنا لمتابعته." action={<Link href="/orders/new" className="text-sm font-bold text-primary" data-testid="link-empty-new-order">ابدأ بطلب جديد</Link>}/>}
      </SectionCard>
      <div className="space-y-5">
        <SectionCard title="صندوق التنبيهات"><div className="space-y-3 p-4">{safeArray(d.alerts).slice(0, 4).map((a) => <Link href={a.href || "/orders"} key={a.id} className="flex gap-3 rounded-xl bg-secondary/10 p-3 transition-colors hover:bg-secondary/20" data-testid={`link-alert-${a.id}`}><CircleAlert className="mt-0.5 shrink-0 text-accent" size={17}/><span><strong className="block text-xs">{a.title}</strong><small className="mt-1 block text-[11px] leading-5 text-muted-foreground">{a.description}</small></span></Link>)}{safeArray(d.alerts).length === 0 && <p className="p-4 text-center text-sm text-muted-foreground">لا توجد تنبيهات معلقة</p>}</div></SectionCard>
        <SectionCard title="لقطة سريعة"><div className="grid grid-cols-2 gap-px bg-border/70">{[{v:d.arrivedUndelivered,label:"وصلت ولم تُسلّم",Icon:Package},{v:d.shipmentsInTransit,label:"شحنات بالطريق",Icon:Truck},{v:d.totalIncome,label:"إجمالي الدخل",Icon:ArrowUpLeft},{v:d.totalExpenses,label:"إجمالي المصروف",Icon:ArrowDownLeft}].map(({v,label,Icon}, i) => <div key={i} className="bg-card p-4"><Icon size={16} className="mb-3 text-accent"/><strong className="block text-lg tabular-nums" dir="ltr">{i > 1 ? <Money value={v}/> : v}</strong><small className="text-[10px] text-muted-foreground">{label}</small></div>)}</div></SectionCard>
      </div>
    </div>
    <div className="mt-5 grid gap-5 lg:grid-cols-2"><SectionCard title="آخر الدفعات"><div className="divide-y divide-border/70">{safeArray(d.recentPayments).slice(0, 4).map((p) => <div key={p.id} className="flex items-center justify-between px-5 py-3.5" data-testid={`row-dashboard-payment-${p.id}`}><div><strong className="text-sm">{p.customerName}</strong><small className="mr-2 text-xs text-muted-foreground">{p.method}</small></div><Money value={p.amount} className="font-bold text-emerald-700"/></div>)}</div></SectionCard><SectionCard title="آخر المصروفات"><div className="divide-y divide-border/70">{safeArray(d.recentExpenses).slice(0, 4).map((x) => <div key={x.id} className="flex items-center justify-between px-5 py-3.5"><div><strong className="text-sm">{x.description}</strong><small className="mr-2 text-xs text-muted-foreground">{x.category}</small></div><Money value={x.amount} className="font-bold text-accent"/></div>)}</div></SectionCard></div>
  </div></AppPage>;
}

export function CustomersPage() {
  const [search, setSearch] = useState(""); const [open, setOpen] = useState(false); const [flash, setFlash] = useState("");
  const params = useMemo(() => search ? { search } : undefined, [search]); const q = useListCustomers(params, { query: { queryKey: getListCustomersQueryKey(params) } }); const create = useCreateCustomer(); const qc = useQueryClient();
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ data: { name: String(f.get("name")), phone: String(f.get("phone")), address: String(f.get("address") || ""), deliveryRequired: f.get("deliveryRequired") === "on", deliveryAddress: String(f.get("deliveryAddress") || "") } }, { onSuccess: () => { setOpen(false); setFlash("تم حفظ العميل بنجاح"); qc.invalidateQueries({ queryKey: getListCustomersQueryKey() }); setTimeout(() => setFlash(""), 2600); } }); };
    return <AppPage><PageHeader eyebrow="العلاقات" title="العملاء" description="ملفات واضحة لكل عميل: الطلبات، المدفوعات، وما تبقى عليه." action={<Button onClick={() => setOpen(true)} data-testid="button-add-customer"><Plus size={17}/> عميل جديد</Button>}/><div className="mb-5 flex flex-col gap-3 rounded-2xl border border-border bg-card p-3 sm:flex-row"><SearchBox value={search} onChange={setSearch} placeholder="ابحث بالاسم أو رقم الهاتف..."/><div className="hidden items-center gap-2 px-3 text-xs text-muted-foreground sm:flex"><Filter size={15}/> {q.data?.length || 0} سجل</div></div><div className="overflow-hidden rounded-2xl border border-card-border bg-card shadow-sm"><QueryState isLoading={q.isLoading} isError={q.isError} onRetry={() => q.refetch()}>{safeArray(q.data).length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-right text-sm"><thead className="bg-muted/60 text-xs text-muted-foreground"><tr><th className="px-5 py-4">العميل</th><th className="px-5 py-4">الهاتف</th><th className="px-5 py-4">الطلبات النشطة</th><th className="px-5 py-4">إجمالي المدفوع</th><th className="px-5 py-4">المتبقي</th><th className="px-5 py-4">آخر تحديث</th></tr></thead><tbody className="divide-y divide-border/70">{safeArray(q.data).map((c) => <tr key={c.id} className="transition-colors hover:bg-muted/40" data-testid={`row-customer-${c.id}`}><td className="px-5 py-4"><Link href={`/customers/${c.id}`} className="flex items-center gap-3 font-bold text-primary hover:underline" data-testid={`link-customer-${c.id}`}><span className="grid size-9 place-items-center rounded-full bg-secondary/25 text-xs font-bold">{c.name.slice(0, 1)}</span>{c.name}</Link></td><td className="px-5 py-4 tabular-nums" dir="ltr">{c.phone}</td><td className="px-5 py-4"><span className="rounded-lg bg-muted px-2 py-1 text-xs font-bold">{c.activeOrders} / {c.totalOrders}</span></td><td className="px-5 py-4"><Money value={c.totalPaid}/></td><td className="px-5 py-4"><Money value={c.remaining} className={c.remaining > 0 ? "font-bold text-accent" : "text-emerald-700"}/></td><td className="px-5 py-4 text-xs text-muted-foreground">{fmtDate(c.updatedAt)}</td></tr>)}</tbody></table></div> : <EmptyState title="لا يوجد عملاء بعد" description="أضف أول عميل لتبدأ ربط الطلبات والمدفوعات بملف واحد." action={<Button onClick={() => setOpen(true)}>إضافة عميل</Button>}/>}</QueryState></div>{flash && <Flash message={flash}/>}<Modal open={open} onClose={() => setOpen(false)} title="إضافة عميل جديد"><form onSubmit={submit} className="space-y-4"><Input name="name" label="الاسم الكامل" required placeholder="مثال: نور حداد" data-testid="input-customer-name"/><Input name="phone" label="رقم الهاتف" required dir="ltr" placeholder="05x xxx xxxx" data-testid="input-customer-phone"/><Input name="address" label="العنوان" placeholder="المدينة، الحي..." data-testid="input-customer-address"/><Input name="deliveryAddress" label="عنوان التسليم (إن اختلف)" placeholder="اتركه فارغاً إن لم يلزم" data-testid="input-customer-delivery-address"/><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="deliveryRequired" className="size-4 accent-[hsl(var(--primary))]" data-testid="input-customer-delivery-required"/> يحتاج إلى توصيل</label><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={() => setOpen(false)}>إلغاء</Button><Button type="submit" disabled={create.isPending}>{create.isPending && <Spinner/>} حفظ العميل</Button></div></form></Modal></AppPage>;
}

export function CustomerProfilePage() {
  const { id } = useParams<{ id: string }>(); const customerId = Number(id); const q = useGetCustomer(customerId, { query: { queryKey: getGetCustomerQueryKey(customerId) } }); const [edit, setEdit] = useState(false); const update = useUpdateCustomer(); const qc = useQueryClient(); const c = q.data;
  if (q.isLoading) return <AppPage><PageSkeleton/></AppPage>; if (q.isError || !c) return <AppPage><QueryState isError onRetry={() => q.refetch()}/></AppPage>;
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); update.mutate({ id: customerId, data: { name: String(f.get("name")), phone: String(f.get("phone")), address: String(f.get("address") || ""), notes: String(f.get("notes") || "") } }, { onSuccess: () => { setEdit(false); qc.invalidateQueries({ queryKey: getGetCustomerQueryKey(customerId) }); } }); };
  return <AppPage><div className="mb-5 flex items-center gap-2 text-xs text-muted-foreground"><Link href="/customers" className="hover:text-primary" data-testid="link-back-customers">العملاء</Link><ChevronLeft size={13}/><span>{c.name}</span></div><PageHeader eyebrow="ملف العميل" title={c.name} description={`${c.phone} · انضم في ${fmtDate(c.createdAt)}`} action={<Button variant="ghost" onClick={() => setEdit(true)} data-testid="button-edit-customer">تعديل البيانات</Button>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="إجمالي الطلبات" value={c.totalOrders} sub={`${c.activeOrders} طلب نشط`} icon={ShoppingCart}/><StatCard label="إجمالي المحصل" value={<Money value={c.totalPaid}/>} sub="دفعات مؤكدة" icon={CircleDollarSign} tone="mint"/><StatCard label="إجمالي الفواتير" value={<Money value={c.totalCharged}/>} sub="السعر المحصل من العميل" icon={Receipt} tone="gold"/><StatCard label="الرصيد المتبقي" value={<Money value={c.remaining}/>} sub={c.remaining > 0 ? "بانتظار التحصيل" : "الحساب مسدد"} icon={WalletCards} tone="coral"/></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.3fr_.8fr]"><SectionCard title="طلبات العميل" action={<Link href="/orders/new" className="text-xs font-bold text-primary" data-testid="link-profile-new-order">طلب جديد</Link>}><div className="divide-y divide-border/70">{safeArray(c.orders).map((o) => <Link href={`/orders/${o.id}`} key={o.id} className="flex items-center gap-3 px-5 py-4 hover:bg-muted/40" data-testid={`link-profile-order-${o.id}`}><span className="grid size-9 place-items-center rounded-xl bg-secondary/20 text-primary"><Package size={17}/></span><div className="min-w-0 flex-1"><strong className="block text-sm">{o.orderNumber}</strong><small className="text-xs text-muted-foreground">{fmtDate(o.orderDate)} · {o.itemCount} منتجات</small></div><div className="text-left"><Money value={o.remaining} className="text-sm font-bold"/><Status value={o.status}/></div></Link>)}{safeArray(c.orders).length === 0 && <EmptyState title="لا توجد طلبات" description="لم يتم ربط أي طلب بهذا العميل بعد."/>}</div></SectionCard><SectionCard title="سجل الدفعات"><div className="divide-y divide-border/70">{safeArray(c.payments).map((p) => <div key={p.id} className="flex items-center justify-between px-5 py-4"><div><strong className="block text-sm">{fmtDate(p.paymentDate)}</strong><small className="text-xs text-muted-foreground">{p.method} · {p.type}</small></div><Money value={p.amount} className="font-bold text-emerald-700"/></div>)}{safeArray(c.payments).length === 0 && <EmptyState title="لا توجد دفعات" description="ستظهر الدفعات هنا فور تسجيلها."/>}</div></SectionCard></div><Modal open={edit} onClose={() => setEdit(false)} title="تعديل بيانات العميل"><form onSubmit={submit} className="space-y-4"><Input name="name" label="الاسم الكامل" defaultValue={c.name} required/><Input name="phone" label="رقم الهاتف" defaultValue={c.phone} required dir="ltr"/><Input name="address" label="العنوان" defaultValue={c.address || ""}/><Textarea name="notes" label="ملاحظات" defaultValue={c.notes || ""}/><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={() => setEdit(false)}>إلغاء</Button><Button type="submit" disabled={update.isPending}>{update.isPending && <Spinner/>} حفظ التعديلات</Button></div></form></Modal></AppPage>;
}

export function OrdersPage() {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const params = useMemo(() => ({ ...(search ? { search } : {}), ...(status ? { status } : {}) }), [search, status]); const q = useListOrders(params, { query: { queryKey: getListOrdersQueryKey(params) } });
  return <AppPage><PageHeader eyebrow="المتابعة اليومية" title="الطلبات" description="من طلب العميل إلى آخر منتج وصل — كل مرحلة مرئية وقابلة للتصرف." action={<Link href="/orders/new" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground" data-testid="link-new-order"><Plus size={17}/> طلب جديد</Link>}/><div className="mb-5 flex flex-col gap-3 rounded-2xl border border-border bg-card p-3 sm:flex-row"><SearchBox value={search} onChange={setSearch} placeholder="ابحث برقم الطلب أو اسم العميل..."/><Select value={status} onChange={(e) => setStatus(e.target.value)} className="sm:w-48" aria-label="تصفية حسب الحالة"><option value="">كل الحالات</option><option value="pending">قيد الانتظار</option><option value="processing">قيد التنفيذ</option><option value="arrived">وصل</option><option value="delivered">تم التسليم</option></Select></div><div className="overflow-hidden rounded-2xl border border-card-border bg-card"><QueryState isLoading={q.isLoading} isError={q.isError} onRetry={() => q.refetch()}>{safeArray(q.data).length ? <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-right text-sm"><thead className="bg-muted/60 text-xs text-muted-foreground"><tr><th className="px-5 py-4">الطلب</th><th className="px-5 py-4">العميل</th><th className="px-5 py-4">المرحلة</th><th className="px-5 py-4">السعر المحصل</th><th className="px-5 py-4">SHEIN الفعلي</th><th className="px-5 py-4">المدفوع / المتبقي</th><th className="px-5 py-4">التسليم</th></tr></thead><tbody className="divide-y divide-border/70">{safeArray(q.data).map((o) => <tr key={o.id} className="hover:bg-muted/40" data-testid={`row-order-${o.id}`}><td className="px-5 py-4"><Link href={`/orders/${o.id}`} className="font-bold text-primary hover:underline" data-testid={`link-order-${o.id}`}>{o.orderNumber}</Link><small className="mt-1 block text-xs text-muted-foreground">{fmtDate(o.orderDate)}</small></td><td className="px-5 py-4"><strong>{o.customerName}</strong><small className="mt-1 block text-xs text-muted-foreground" dir="ltr">{o.customerPhone}</small></td><td className="px-5 py-4"><Status value={o.status}/><small className="mt-1 block text-xs text-muted-foreground">{o.itemCount} منتجات · {o.arrivedCount} وصل</small></td><td className="px-5 py-4 font-bold"><Money value={o.totalSelling}/></td><td className="px-5 py-4"><Money value={o.totalSheinCost}/></td><td className="px-5 py-4"><Money value={o.totalPaid} className="text-emerald-700"/><small className="mr-2 text-xs text-accent">باقي <Money value={o.remaining}/></small></td><td className="px-5 py-4"><Status value={o.deliveryStatus}/></td></tr>)}</tbody></table></div> : <EmptyState title="لا توجد طلبات مطابقة" description="جرّب تغيير البحث أو سجّل طلباً جديداً." action={<Link href="/orders/new" className="text-sm font-bold text-primary" data-testid="link-empty-orders">تسجيل طلب</Link>}/>}</QueryState></div></AppPage>;
}

export function NewOrderPage() {
  const [, setLocation] = useLocation(); const customers = useListCustomers(undefined, { query: { queryKey: getListCustomersQueryKey(undefined) } }); const create = useCreateOrder(); const [items, setItems] = useState([{ name: "", quantity: 1, sellingPrice: "", commission: "", sheinCost: "", productUrl: "", imagePath: "", notes: "" }]); const [error, setError] = useState("");
  const updateItem = (i: number, key: string, value: string) => setItems((all) => all.map((x, n) => n === i ? { ...x, [key]: value } : x));
  const total = items.reduce((s, x) => s + (Number(x.sellingPrice || 0) + Number(x.commission || 0)) * Number(x.quantity || 0), 0);
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); if (!String(f.get("customerId"))) return setError("اختر العميل أولاً"); if (items.some((x) => !x.name || !x.sellingPrice || !x.sheinCost)) return setError("أكمل اسم المنتج والسعر المحصل وتكلفة SHEIN لكل منتج"); setError(""); create.mutate({ data: { customerId: Number(f.get("customerId")), orderDate: String(f.get("orderDate")), deliveryMethod: String(f.get("deliveryMethod")) as "pickup" | "delivery", deliveryFee: Number(f.get("deliveryFee") || 0), deliveryAddress: String(f.get("deliveryAddress") || "") || null, notes: String(f.get("notes") || "") || null, items: items.map((x) => ({ name: x.name, quantity: Number(x.quantity), sellingPrice: Number(x.sellingPrice), commission: Number(x.commission || 0), sheinCost: Number(x.sheinCost), productUrl: x.productUrl || null, imagePath: x.imagePath || null, notes: x.notes || null })) } }, { onSuccess: (o) => setLocation(`/orders/${o.id}`) }); };
  return <AppPage><div className="mb-5 flex items-center gap-2 text-xs text-muted-foreground"><Link href="/orders" className="hover:text-primary" data-testid="link-back-orders">الطلبات</Link><ChevronLeft size={13}/><span>طلب جديد</span></div><PageHeader eyebrow="عملية جديدة" title="تسجيل طلب عميل" description="سجّل السعر المحصل وتكلفة SHEIN الفعلية منفصلين — هذا ما يحفظ دقة الربح."/><form onSubmit={submit}><div className="grid gap-5 xl:grid-cols-[1fr_330px]"><div className="space-y-5"><SectionCard title="بيانات الطلب"><div className="grid gap-4 p-5 sm:grid-cols-2"><Select label="العميل" name="customerId" required data-testid="select-order-customer"><option value="">اختر العميل...</option>{safeArray(customers.data).map((c) => <option value={c.id} key={c.id}>{c.name} · {c.phone}</option>)}</Select><Input label="تاريخ الطلب" name="orderDate" type="date" defaultValue={today} required data-testid="input-order-date"/><Select label="طريقة الاستلام" name="deliveryMethod" defaultValue="pickup" data-testid="select-delivery-method"><option value="pickup">استلام من الشراكة</option><option value="delivery">توصيل للعميل</option></Select><Input label="رسوم التوصيل" name="deliveryFee" type="number" min="0" step="0.01" defaultValue="0" data-testid="input-delivery-fee"/><div className="sm:col-span-2"><Input label="عنوان التسليم" name="deliveryAddress" placeholder="يُستخدم عند اختيار التوصيل"/><div className="mt-4"><Textarea label="ملاحظات الطلب" name="notes" placeholder="أي تفاصيل مهمة للشريك الآخر..."/></div></div></div></SectionCard><SectionCard title="منتجات الطلب" action={<Button type="button" variant="secondary" onClick={() => setItems((x) => [...x, { name: "", quantity: 1, sellingPrice: "", commission: "", sheinCost: "", productUrl: "", imagePath: "", notes: "" }])} className="min-h-9 px-3 text-xs" data-testid="button-add-order-item"><Plus size={14}/> منتج</Button>}><div className="space-y-4 p-5">{items.map((item, i) => <div key={i} className="rounded-xl border border-border bg-background/60 p-4" data-testid={`card-order-item-${i}`}><div className="mb-3 flex items-center justify-between"><span className="text-xs font-bold text-muted-foreground">منتج {i + 1}</span>{items.length > 1 && <button type="button" onClick={() => setItems((x) => x.filter((_, n) => n !== i))} className="text-xs font-bold text-destructive" data-testid={`button-remove-order-item-${i}`}>إزالة</button>}</div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Input label="اسم المنتج" value={item.name} onChange={(e) => updateItem(i, "name", e.target.value)} required data-testid={`input-item-name-${i}`}/><Input label="الكمية" type="number" min="1" value={item.quantity} onChange={(e) => updateItem(i, "quantity", e.target.value)} required/><Input label="السعر المحصل" type="number" min="0" step="0.01" value={item.sellingPrice} onChange={(e) => updateItem(i, "sellingPrice", e.target.value)} required/><Input label="تكلفة SHEIN الفعلية" type="number" min="0" step="0.01" value={item.sheinCost} onChange={(e) => updateItem(i, "sheinCost", e.target.value)} required/><Input label="عمولة الشراكة" type="number" min="0" step="0.01" value={item.commission} onChange={(e) => updateItem(i, "commission", e.target.value)}/><Input label="رابط المنتج" value={item.productUrl} onChange={(e) => updateItem(i, "productUrl", e.target.value)} className="sm:col-span-2" placeholder="https://..."/><UploadField label="صورة المنتج" value={item.imagePath} onChange={(path) => updateItem(i, "imagePath", path)}/></div></div>)}</div></SectionCard></div><aside className="h-fit rounded-2xl bg-primary p-5 text-primary-foreground shadow-lg shadow-primary/10 xl:sticky xl:top-24"><p className="text-xs font-bold text-primary-foreground/65">ملخص الطلب</p><div className="mt-7 space-y-4 border-b border-primary-foreground/15 pb-5"><div className="flex justify-between text-sm"><span className="text-primary-foreground/70">عدد المنتجات</span><strong>{items.length}</strong></div><div className="flex justify-between text-sm"><span className="text-primary-foreground/70">الوحدات</span><strong>{items.reduce((s, x) => s + Number(x.quantity || 0), 0)}</strong></div></div><div className="mt-5 flex items-end justify-between"><span className="text-xs text-primary-foreground/70">إجمالي السعر المحصل</span><strong className="font-display text-2xl" dir="ltr"><Money value={total} sign/></strong></div>{error && <p className="mt-4 rounded-lg bg-destructive/30 px-3 py-2 text-xs font-bold" data-testid="status-order-form-error">{error}</p>}<Button type="submit" disabled={create.isPending} className="mt-7 w-full bg-secondary text-secondary-foreground hover:brightness-95" data-testid="button-submit-order">{create.isPending && <Spinner/>} حفظ الطلب</Button><Link href="/orders" className="mt-3 block text-center text-xs font-bold text-primary-foreground/60 hover:text-primary-foreground" data-testid="link-cancel-order">إلغاء</Link></aside></div></form></AppPage>;
}

export function OrderDetailsPage() {
  const { id } = useParams<{ id: string }>(); const orderId = Number(id); const q = useGetOrder(orderId, { query: { queryKey: getGetOrderQueryKey(orderId) } }); const updateItem = useUpdateOrderItem(); const qc = useQueryClient(); const [flash, setFlash] = useState(""); const o = q.data;
  if (q.isLoading) return <AppPage><PageSkeleton/></AppPage>; if (q.isError || !o) return <AppPage><QueryState isError onRetry={() => q.refetch()}/></AppPage>;
  const saveStatus = (itemId: number, productStatus: string, deliveryStatus: string) => updateItem.mutate({ id: orderId, itemId, data: { productStatus, deliveryStatus } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetOrderQueryKey(orderId) }); setFlash("تم تحديث حالة المنتج"); setTimeout(() => setFlash(""), 2200); } });
  return <AppPage><div className="mb-5 flex items-center gap-2 text-xs text-muted-foreground"><Link href="/orders" className="hover:text-primary" data-testid="link-back-order-list">الطلبات</Link><ChevronLeft size={13}/><span>{o.orderNumber}</span></div><PageHeader eyebrow={`طلب ${o.orderNumber}`} title={o.customerName} description={`${fmtDate(o.orderDate)} · ${o.customerPhone}`} action={<Status value={o.status}/>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="السعر المحصل" value={<Money value={o.totalSelling}/>} sub="إجمالي فاتورة العميل" icon={Receipt}/><StatCard label="تكلفة SHEIN الفعلية" value={<Money value={o.totalSheinCost}/>} sub="تكلفة الشراء" icon={ShoppingCart} tone="gold"/><StatCard label="العمولة" value={<Money value={o.totalCommission}/>} sub="حصة الشراكة" icon={TrendingUp} tone="mint"/><StatCard label="المتبقي من العميل" value={<Money value={o.remaining}/>} sub={`${o.totalPaid > 0 ? "تم تحصيل دفعة" : "لم تُسجل دفعة"}`} icon={WalletCards} tone="coral"/></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.5fr_.65fr]"><SectionCard title={`المنتجات · ${o.items.length}`}><div className="divide-y divide-border/70">{safeArray(o.items).map((item) => <div key={item.id} className="p-5" data-testid={`row-order-item-${item.id}`}><div className="flex flex-col justify-between gap-4 lg:flex-row"><div className="flex gap-3"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-secondary/20 text-primary"><Package size={18}/></span><div><strong className="block text-sm">{item.name}</strong><small className="mt-1 block text-xs text-muted-foreground">كمية {item.quantity} · سعر محصل <Money value={item.totalSelling}/></small><small className="mt-1 block text-xs text-muted-foreground">SHEIN فعلي <Money value={item.totalSheinCost}/> · عمولة <Money value={item.totalCommission}/></small></div></div><div className="flex flex-wrap gap-2"><Select value={item.productStatus} onChange={(e) => saveStatus(item.id, e.target.value, item.deliveryStatus)} aria-label="حالة المنتج" className="min-h-9 w-36 text-xs"><option value="pending">بانتظار الشراء</option><option value="ordered">تم الشراء</option><option value="arrived">وصل</option><option value="missing">ناقص</option></Select><Select value={item.deliveryStatus} onChange={(e) => saveStatus(item.id, item.productStatus, e.target.value)} aria-label="حالة التسليم" className="min-h-9 w-36 text-xs"><option value="pending">لم يُسلّم</option><option value="ready">جاهز للتسليم</option><option value="delivered">تم التسليم</option></Select></div></div></div>)}</div></SectionCard><div className="space-y-5"><SectionCard title="تفاصيل العميل"><div className="space-y-4 p-5 text-sm"><div className="flex items-center gap-3"><UserRound size={17} className="text-accent"/><Link href={`/customers/${o.customerId}`} className="font-bold text-primary hover:underline" data-testid="link-order-customer">{o.customerName}</Link></div><div className="flex items-center gap-3"><Truck size={17} className="text-accent"/><span>{o.deliveryMethod === "delivery" ? o.deliveryAddress || "عنوان غير محدد" : "استلام من الشراكة"}</span></div>{o.notes && <p className="rounded-xl bg-muted p-3 text-xs leading-6">{o.notes}</p>}</div></SectionCard><SectionCard title="تقدم الطلب"><div className="p-5"><div className="mb-3 flex justify-between text-xs"><span>المنتجات الواصلة</span><strong>{o.arrivedCount} / {o.itemCount}</strong></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-secondary transition-all" style={{width: `${o.itemCount ? (o.arrivedCount / o.itemCount) * 100 : 0}%`}}/></div><div className="mt-5 flex items-center gap-2 text-xs text-muted-foreground"><Check size={15} className="text-emerald-600"/> {o.deliveryStatus || "بانتظار التحديث"}</div></div></SectionCard></div></div>{flash && <Flash message={flash}/>}</AppPage>;
}

export function PaymentsPage() {
  const [search, setSearch] = useState("");
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<Payment | null>(null);
  const [deleting, setDeleting] = useState<Payment | null>(null);
  const params = useMemo(() => search ? { search } : undefined, [search]);
  const q = useListPayments(params, { query: { queryKey: getListPaymentsQueryKey(params) } });
  const customers = useListCustomers(undefined, { query: { queryKey: getListCustomersQueryKey(undefined) } });
  const create = useCreatePayment();
  const update = useUpdatePayment();
  const remove = useDeletePayment();
  const qc = useQueryClient();
  const { flash, notify } = useFlash();
  const closeForm = () => { setOpen(false); setEditing(null); };
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const data = { customerId: Number(f.get("customerId")), orderId: f.get("orderId") ? Number(f.get("orderId")) : null, amount: Number(f.get("amount")), type: String(f.get("type")) as "initial_deposit" | "remaining" | "partial" | "refund" | "other", method: String(f.get("method")), paymentDate: String(f.get("paymentDate")), notes: String(f.get("notes") || "") || null };
    const done = { onSuccess: () => { closeForm(); void qc.invalidateQueries(); notify(editing ? "تم تعديل الدفعة بنجاح" : "تم تسجيل الدفعة بنجاح"); }, onError: () => notify("تعذر حفظ الدفعة. تحقق من البيانات والاتصال.", true) };
    if (editing) update.mutate({ id: editing.id, data }, done);
    else create.mutate({ data: { ...data, notes: data.notes || "" } }, done);
  };
  const confirmDelete = () => { if (!deleting) return; remove.mutate({ id: deleting.id }, { onSuccess: () => { setDeleting(null); void qc.invalidateQueries(); notify("تم حذف الدفعة بنجاح"); }, onError: () => notify("تعذر حذف الدفعة. قد تكون مرتبطة بسجل لا يمكن حذفه.", true) }); };
  const busy = create.isPending || update.isPending;
  return <AppPage><PageHeader eyebrow="الأموال" title="الدفعات" description="دفتر واضح لما دفعه العملاء، ومتى، وعلى أي طلب." action={<Button onClick={() => { setEditing(null); setOpen(true); }} data-testid="button-add-payment"><Plus size={17}/> تسجيل دفعة</Button>}/><div className="mb-5 flex gap-3 rounded-2xl border border-border bg-card p-3"><SearchBox value={search} onChange={setSearch} placeholder="ابحث باسم العميل أو رقم الطلب..."/></div><div className="overflow-hidden rounded-2xl border border-card-border bg-card"><QueryState isLoading={q.isLoading} isError={q.isError} onRetry={() => q.refetch()}>{safeArray(q.data).length ? <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-right text-sm"><thead className="bg-muted/60 text-xs text-muted-foreground"><tr><th className="px-5 py-4">العميل</th><th className="px-5 py-4">الطلب</th><th className="px-5 py-4">التاريخ</th><th className="px-5 py-4">الطريقة</th><th className="px-5 py-4">نوع الدفعة</th><th className="px-5 py-4">المبلغ</th><th className="px-5 py-4">الحالة</th><th className="px-5 py-4">إجراءات</th></tr></thead><tbody className="divide-y divide-border/70">{safeArray(q.data).map((p) => <tr key={p.id} className="hover:bg-muted/40" data-testid={`row-payment-${p.id}`}><td className="px-5 py-4 font-bold">{p.customerName}</td><td className="px-5 py-4 text-primary">{p.orderId ? `#${p.orderId}` : "عام"}</td><td className="px-5 py-4 text-xs text-muted-foreground">{fmtDate(p.paymentDate)}</td><td className="px-5 py-4">{p.method}</td><td className="px-5 py-4 text-xs">{p.type}</td><td className="px-5 py-4 font-bold text-emerald-700"><Money value={p.amount}/></td><td className="px-5 py-4"><Status value={p.status}/></td><td className="px-5 py-4"><div className="flex gap-2"><Button variant="ghost" className="min-h-9 px-3 text-xs" onClick={() => { setEditing(p); setOpen(true); }} data-testid={`button-edit-payment-${p.id}`} title="تعديل الدفعة"><Edit3 size={14}/> تعديل</Button><Button variant="danger" className="min-h-9 px-3 text-xs" onClick={() => setDeleting(p)} data-testid={`button-delete-payment-${p.id}`} title="حذف الدفعة"><Trash2 size={14}/> حذف</Button></div></td></tr>)}</tbody></table></div> : <EmptyState title="لا توجد دفعات" description="سجّل دفعة أولى عند تأكيد الطلب، ثم تابع المتبقي بثقة." action={<Button onClick={() => setOpen(true)}>تسجيل دفعة</Button>}/>}</QueryState></div>{flash && <Flash message={flash.message} error={flash.error}/>}<Modal open={open} onClose={closeForm} title={editing ? "تعديل الدفعة" : "تسجيل دفعة يدوية"}><form key={editing?.id ?? "new-payment"} onSubmit={submit} className="space-y-4"><Select label="العميل" name="customerId" defaultValue={editing?.customerId ?? ""} required data-testid="select-payment-customer"><option value="">اختر العميل...</option>{safeArray(customers.data).map((c) => <option value={c.id} key={c.id}>{c.name}</option>)}</Select><div className="grid gap-4 sm:grid-cols-2"><Input label="رقم الطلب (اختياري)" name="orderId" type="number" defaultValue={editing?.orderId ?? ""} placeholder="مثال: 1042"/><Input label="المبلغ" name="amount" type="number" min="0.01" step="0.01" defaultValue={editing?.amount ?? ""} required data-testid="input-payment-amount"/><Select label="نوع الدفعة" name="type" defaultValue={editing?.type || "partial"}><option value="initial_deposit">دفعة أولى</option><option value="partial">دفعة جزئية</option><option value="remaining">تسديد المتبقي</option><option value="refund">استرداد</option><option value="other">أخرى</option></Select><Select label="طريقة الدفع" name="method" defaultValue={editing?.method || "نقدي"}><option>نقدي</option><option>تحويل بنكي</option><option>بطاقة</option><option>تطبيق دفع</option></Select><Input label="التاريخ" name="paymentDate" type="date" defaultValue={editing?.paymentDate?.slice(0, 10) || today} required/></div><Textarea label="ملاحظات" name="notes" defaultValue={editing?.notes || ""}/><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={closeForm}>إلغاء</Button><Button type="submit" disabled={busy}>{busy && <Spinner/>} {editing ? "حفظ التعديلات" : "حفظ الدفعة"}</Button></div></form></Modal><ConfirmModal open={!!deleting} onClose={() => setDeleting(null)} title="تأكيد حذف الدفعة" description={`سيتم حذف دفعة ${deleting ? `#${deleting.id}` : ""} وتحديث رصيد العميل والمحفظة. لا يمكن التراجع عن هذا الإجراء.`} pending={remove.isPending} onConfirm={confirmDelete}/></AppPage>;
}

export function PurchasesPage() {
  const q = useListPurchases({ query: { queryKey: getListPurchasesQueryKey() } });
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<SheinPurchase | null>(null);
  const [deleting, setDeleting] = useState<SheinPurchase | null>(null);
  const [invoicePath, setInvoicePath] = useState("");
  const create = useCreatePurchase();
  const update = useUpdatePurchase();
  const remove = useDeletePurchase();
  const qc = useQueryClient();
  const { flash, notify } = useFlash();
  const closeForm = () => { setOpen(false); setEditing(null); setInvoicePath(""); };
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const values = { invoiceNumber: String(f.get("invoiceNumber")), purchaseDate: String(f.get("purchaseDate")), totalAmount: Number(f.get("totalAmount")), currency: "ILS", notes: String(f.get("notes") || "") || null };
    const done = { onSuccess: () => { closeForm(); void qc.invalidateQueries(); notify(editing ? "تم تعديل فاتورة SHEIN بنجاح" : "تم حفظ فاتورة SHEIN بنجاح"); }, onError: () => notify("تعذر حفظ الفاتورة. تحقق من البيانات والاتصال.", true) };
    if (editing) update.mutate({ id: editing.id, data: values }, done);
    else create.mutate({ data: { ...values, notes: values.notes || "", invoicePath: invoicePath || null, itemIds: [] } }, done);
  };
  const confirmDelete = () => { if (!deleting) return; remove.mutate({ id: deleting.id }, { onSuccess: () => { setDeleting(null); void qc.invalidateQueries(); notify("تم حذف فاتورة SHEIN بنجاح"); }, onError: () => notify("تعذر حذف الفاتورة. لا يمكن حذف فاتورة مرتبطة بشحنة.", true) }); };
  const busy = create.isPending || update.isPending;
  return <AppPage><PageHeader eyebrow="الشراء" title="مشتريات SHEIN" description="اربط فواتير الشراء بالمنتجات حتى تبقى تكلفة SHEIN الفعلية مفصولة عن السعر المحصل." action={<Button onClick={() => { setEditing(null); setOpen(true); }} data-testid="button-add-purchase"><Plus size={17}/> فاتورة جديدة</Button>}/><SectionCard title="الفواتير المسجلة" action={<span className="text-xs text-muted-foreground">{safeArray(q.data).length} فاتورة</span>}><QueryState isLoading={q.isLoading} isError={q.isError} onRetry={() => q.refetch()}>{safeArray(q.data).length ? <div className="divide-y divide-border/70">{safeArray(q.data).map((p) => <div key={p.id} className="flex flex-col gap-4 px-5 py-4 sm:flex-row sm:items-center" data-testid={`row-purchase-${p.id}`}><span className="grid size-10 place-items-center rounded-xl bg-secondary/20 text-primary"><Receipt size={18}/></span><div className="min-w-0 flex-1"><strong className="block text-sm">فاتورة {p.invoiceNumber}</strong><small className="text-xs text-muted-foreground">{fmtDate(p.purchaseDate)} · {p.itemIds.length} منتجات مرتبطة</small></div><div className="text-right sm:text-left"><Money value={p.totalAmount} className="font-display text-lg font-bold"/><small className="mr-2 text-xs text-muted-foreground">{p.currency}</small></div><Status value={p.status}/><div className="flex gap-2 sm:mr-2"><Button variant="ghost" className="min-h-9 px-3 text-xs" onClick={() => { setEditing(p); setOpen(true); }} data-testid={`button-edit-purchase-${p.id}`} title="تعديل الفاتورة"><Edit3 size={14}/> تعديل</Button><Button variant="danger" className="min-h-9 px-3 text-xs" onClick={() => setDeleting(p)} data-testid={`button-delete-purchase-${p.id}`} title="حذف الفاتورة"><Trash2 size={14}/> حذف</Button></div></div>)}</div> : <EmptyState title="لا توجد فواتير شراء" description="أضف أول فاتورة SHEIN ثم عيّن منتجاتها عند وصول الشحنة." action={<Button onClick={() => setOpen(true)}>إضافة فاتورة</Button>}/>}</QueryState></SectionCard>{flash && <Flash message={flash.message} error={flash.error}/>}<Modal open={open} onClose={closeForm} title={editing ? "تعديل فاتورة شراء" : "إضافة فاتورة شراء"}><form key={editing?.id ?? "new-purchase"} onSubmit={submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Input label="رقم الفاتورة" name="invoiceNumber" required defaultValue={editing?.invoiceNumber || ""} placeholder="SH-2024-018"/><Input label="تاريخ الشراء" name="purchaseDate" type="date" defaultValue={editing?.purchaseDate?.slice(0, 10) || today} required/><Input label="الإجمالي بالشيكل" name="totalAmount" type="number" min="0" step="0.01" required defaultValue={editing?.totalAmount ?? ""}/></div>{!editing && <UploadField label="صورة أو ملف الفاتورة" value={invoicePath} onChange={setInvoicePath} accept="image/*,.pdf"/>}{editing?.invoicePath && <p className="rounded-xl bg-muted p-3 text-xs text-muted-foreground">يوجد ملف مرفق بهذه الفاتورة. يمكن تحديث بياناتها دون تغيير الملف المرفق.</p>}<Textarea label="ملاحظات" name="notes" defaultValue={editing?.notes || ""} placeholder="مصدر الفاتورة أو ملاحظة للشريك الآخر..."/><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={closeForm}>إلغاء</Button><Button type="submit" disabled={busy}>{busy && <Spinner/>} {editing ? "حفظ التعديلات" : "حفظ الفاتورة"}</Button></div></form></Modal><ConfirmModal open={!!deleting} onClose={() => setDeleting(null)} title="تأكيد حذف فاتورة SHEIN" description={`سيتم حذف فاتورة ${deleting?.invoiceNumber || ""}. لا يمكن حذف الفاتورة إذا كانت مرتبطة بشحنة.`} pending={remove.isPending} onConfirm={confirmDelete}/></AppPage>;
}

export function ShipmentsPage() {
  const q = useListShipments({ query: { queryKey: getListShipmentsQueryKey() } });
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState<number | null>(null);
  const [editing, setEditing] = useState<Shipment | null>(null);
  const [deleting, setDeleting] = useState<Shipment | null>(null);
  const create = useCreateShipment();
  const update = useUpdateShipment();
  const remove = useDeleteShipment();
  const qc = useQueryClient();
  const { flash, notify } = useFlash();
  const closeForm = () => { setOpen(false); setEditing(null); };
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const data = { shipmentNumber: String(f.get("shipmentNumber")), company: String(f.get("company")), trackingNumber: String(f.get("trackingNumber") || "") || null, shipmentDate: String(f.get("shipmentDate")), arrivalDate: editing?.arrivalDate || null, shippingCost: Number(f.get("shippingCost") || 0), currency: "ILS", status: String(f.get("status") || editing?.status || "in_transit"), purchaseIds: editing?.purchaseIds || [], notes: String(f.get("notes") || "") || null };
    const done = { onSuccess: () => { closeForm(); void qc.invalidateQueries(); notify(editing ? "تم تعديل الشحنة بنجاح" : "تم إنشاء الشحنة بنجاح"); }, onError: () => notify("تعذر حفظ الشحنة. تحقق من البيانات والاتصال.", true) };
    if (editing) update.mutate({ id: editing.id, data }, done);
    else create.mutate({ data: { ...data, trackingNumber: data.trackingNumber || "", notes: data.notes || "" } }, done);
  };
  const toggleArrival = (s: Shipment) => { setSelected(s.id); update.mutate({ id: s.id, data: { status: s.status === "arrived" ? "in_transit" : "arrived", arrivalDate: s.status === "arrived" ? null : today } }, { onSuccess: () => { void qc.invalidateQueries(); notify("تم تحديث حالة الشحنة"); setSelected(null); }, onError: () => { setSelected(null); notify("تعذر تحديث حالة الشحنة.", true); } }); };
  const confirmDelete = () => { if (!deleting) return; remove.mutate({ id: deleting.id }, { onSuccess: () => { setDeleting(null); void qc.invalidateQueries(); notify("تم حذف الشحنة بنجاح"); }, onError: () => notify("تعذر حذف الشحنة. تحقق من أنها غير مرتبطة بسجل لا يمكن حذفه.", true) }); };
  const busy = create.isPending || update.isPending;
  return <AppPage><PageHeader eyebrow="الاستلام والتسليم" title="الشحنات" description="تابع الطريق من فاتورة الشراء إلى طاولة الاستلام، ثم عيّن المنتجات للطلبات." action={<Button onClick={() => { setEditing(null); setOpen(true); }} data-testid="button-add-shipment"><Plus size={17}/> شحنة جديدة</Button>}/><div className="grid gap-5">{safeArray(q.data).length === 0 && !q.isLoading && !q.isError ? <EmptyState title="لا توجد شحنات بالطريق" description="أنشئ شحنة واربطها بالفواتير عندما يتم الشراء." action={<Button onClick={() => setOpen(true)}>إنشاء شحنة</Button>}/> : <QueryState isLoading={q.isLoading} isError={q.isError} onRetry={() => q.refetch()}>{safeArray(q.data).map((s) => <SectionCard key={s.id} title={s.shipmentNumber} action={<div className="flex items-center gap-2"><Status value={s.status}/><Button variant="ghost" className="min-h-9 px-3 text-xs" onClick={() => { setEditing(s); setOpen(true); }} data-testid={`button-edit-shipment-${s.id}`} title="تعديل الشحنة"><Edit3 size={14}/> تعديل</Button><Button variant="danger" className="min-h-9 px-3 text-xs" onClick={() => setDeleting(s)} data-testid={`button-delete-shipment-${s.id}`} title="حذف الشحنة"><Trash2 size={14}/> حذف</Button></div>}><div className="grid gap-5 p-5 lg:grid-cols-[1fr_1.2fr]"><div className="grid grid-cols-2 gap-3 text-sm"><div className="rounded-xl bg-muted p-3"><small className="block text-xs text-muted-foreground">شركة الشحن</small><strong className="mt-1 block">{s.company}</strong></div><div className="rounded-xl bg-muted p-3"><small className="block text-xs text-muted-foreground">رقم التتبع</small><strong className="mt-1 block" dir="ltr">{s.trackingNumber || "—"}</strong></div><div className="rounded-xl bg-muted p-3"><small className="block text-xs text-muted-foreground">تاريخ الشحن</small><strong className="mt-1 block">{fmtDate(s.shipmentDate)}</strong></div><div className="rounded-xl bg-muted p-3"><small className="block text-xs text-muted-foreground">تكلفة الشحن</small><strong className="mt-1 block"><Money value={s.shippingCost}/></strong></div></div><div><div className="mb-3 flex items-center justify-between"><h4 className="text-sm font-bold">طابور الاستلام</h4><span className="text-xs text-muted-foreground">{s.receivingItems.length} منتج</span></div>{s.receivingItems.length ? <div className="space-y-2">{s.receivingItems.slice(0, 4).map((i) => <div key={i.id} className="flex items-center justify-between rounded-xl border border-border p-3 text-xs"><span className="font-semibold">{i.name}</span><Status value={i.productStatus}/></div>)}</div> : <p className="rounded-xl bg-muted p-4 text-center text-xs text-muted-foreground">لم يتم تعيين منتجات بعد.</p>}<Button variant="ghost" className="mt-4 min-h-9 px-3 text-xs" onClick={() => toggleArrival(s)} data-testid={`button-update-shipment-${s.id}`}>{s.status === "arrived" ? "إرجاع للطريق" : "تأكيد الوصول"} {selected === s.id && update.isPending && <Spinner/>}</Button></div></div></SectionCard>)}</QueryState>}</div>{flash && <Flash message={flash.message} error={flash.error}/>}<Modal open={open} onClose={closeForm} title={editing ? "تعديل الشحنة" : "إنشاء شحنة"}><form key={editing?.id ?? "new-shipment"} onSubmit={submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Input label="رقم الشحنة" name="shipmentNumber" required defaultValue={editing?.shipmentNumber || ""} placeholder="SEA-024"/><Input label="شركة الشحن" name="company" required defaultValue={editing?.company || ""} placeholder="DHL أو Aramex"/><Input label="رقم التتبع" name="trackingNumber" defaultValue={editing?.trackingNumber || ""} placeholder="اختياري"/><Input label="تاريخ الشحن" name="shipmentDate" type="date" defaultValue={editing?.shipmentDate?.slice(0, 10) || today} required/><Input label="تكلفة الشحن" name="shippingCost" type="number" min="0" step="0.01" defaultValue={editing?.shippingCost ?? 0}/>{editing && <Select label="الحالة" name="status" defaultValue={editing.status}><option value="in_transit">في الطريق</option><option value="arrived">وصلت</option><option value="delivered">تم التسليم</option></Select>}</div><Textarea label="ملاحظات" name="notes" defaultValue={editing?.notes || ""}/><div className="flex justify-end gap-2"><Button type="button" variant="ghost" onClick={closeForm}>إلغاء</Button><Button type="submit" disabled={busy}>{busy && <Spinner/>} {editing ? "حفظ التعديلات" : "إنشاء الشحنة"}</Button></div></form></Modal><ConfirmModal open={!!deleting} onClose={() => setDeleting(null)} title="تأكيد حذف الشحنة" description={`سيتم حذف الشحنة ${deleting?.shipmentNumber || ""} وفك ربط فواتيرها. لا يمكن التراجع عن هذا الإجراء.`} pending={remove.isPending} onConfirm={confirmDelete}/></AppPage>;
}

export function WalletPage() {
  const [search, setSearch] = useState("");
  const params = useMemo(() => search ? { search } : undefined, [search]);
  const q = useGetWallet(params, { query: { queryKey: getGetWalletQueryKey(params) } });
  const [open, setOpen] = useState<"transaction" | "adjustment" | null>(null);
  const [editingExpense, setEditingExpense] = useState<WalletTransaction | null>(null);
  const [deleting, setDeleting] = useState<WalletTransaction | null>(null);
  const create = useCreateWalletTransaction();
  const update = useUpdateWalletTransaction();
  const remove = useDeleteWalletTransaction();
  const adjust = useCreateWalletAdjustment();
  const qc = useQueryClient();
  const { flash, notify } = useFlash();
  const closeForm = () => { setOpen(null); setEditingExpense(null); };
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    if (open === "transaction") {
      const data = { type: String(f.get("type")) as "income" | "expense", amount: Number(f.get("amount")), category: String(f.get("category")), description: String(f.get("description")), transactionDate: String(f.get("transactionDate")) };
      const done = { onSuccess: () => { closeForm(); void qc.invalidateQueries(); notify(editingExpense ? "تم تعديل المصروف اليدوي بنجاح" : "تم تسجيل الحركة بنجاح"); }, onError: () => notify("تعذر حفظ الحركة. تحقق من البيانات والاتصال.", true) };
      if (editingExpense) update.mutate({ id: editingExpense.id, data }, done);
      else create.mutate({ data: { ...data, notes: String(f.get("notes") || "") } }, done);
    } else {
      adjust.mutate({ data: { amount: Number(f.get("amount")), direction: String(f.get("direction")) as "increase" | "decrease", reason: String(f.get("reason")), transactionDate: String(f.get("transactionDate")) } }, { onSuccess: () => { closeForm(); void qc.invalidateQueries(); notify("تم تعديل الرصيد بنجاح"); }, onError: () => notify("تعذر تعديل الرصيد. تحقق من البيانات والاتصال.", true) });
    }
  };
  const confirmDelete = () => { if (!deleting) return; remove.mutate({ id: deleting.id }, { onSuccess: () => { setDeleting(null); void qc.invalidateQueries(); notify("تم حذف المصروف اليدوي بنجاح"); }, onError: () => notify("تعذر حذف المصروف. تحقق من السجل وحاول مرة أخرى.", true) }); };
  const w = q.data;
  if (q.isLoading) return <AppPage><PageSkeleton/></AppPage>;
  if (q.isError || !w) return <AppPage><QueryState isError onRetry={() => q.refetch()}/></AppPage>;
  const manualExpenses = safeArray(w.transactions).filter(isManualExpense);
  const busy = create.isPending || update.isPending || adjust.isPending;
  return <AppPage><PageHeader eyebrow="الأموال" title="المحفظة" description="دفتر نقدي واحد للشراكة: دخل، مصروف، ورصيد متاح يمكن الوثوق به." action={<div className="flex gap-2"><Button variant="ghost" onClick={() => setOpen("adjustment")} data-testid="button-wallet-adjustment">تعديل الرصيد</Button><Button onClick={() => { setEditingExpense(null); setOpen("transaction"); }} data-testid="button-wallet-transaction"><Plus size={17}/> حركة يدوية</Button></div>}/><div className="grid gap-4 sm:grid-cols-3"><StatCard label="الرصيد الحالي" value={<Money value={w.balance}/>} sub="بعد كل الحركات المؤكدة" icon={WalletCards} tone="primary"/><StatCard label="إجمالي الدخل" value={<Money value={w.totalIncome}/>} sub="دفعات ودخل يدوي" icon={ArrowUpLeft} tone="mint"/><StatCard label="إجمالي المصروف" value={<Money value={w.totalExpenses}/>} sub="مشتريات وتكاليف" icon={ArrowDownLeft} tone="coral"/></div><div className="mt-5 rounded-2xl border border-card-border bg-card"><div className="flex flex-col gap-3 border-b border-border/70 px-5 py-4 sm:flex-row sm:items-center"><h3 className="font-display font-bold">دفتر الحركات</h3><div className="sm:mr-auto sm:w-72"><SearchBox value={search} onChange={setSearch} placeholder="ابحث في الوصف أو التصنيف..."/></div></div><QueryState isLoading={q.isLoading} isError={q.isError} onRetry={() => q.refetch()}>{safeArray(w.transactions).length ? <div className="divide-y divide-border/70">{safeArray(w.transactions).map((x) => <div key={x.id} className="flex items-center gap-3 px-5 py-4" data-testid={`row-wallet-${x.id}`}><span className={`grid size-9 place-items-center rounded-xl ${x.type === "income" ? "bg-emerald-100 text-emerald-700" : "bg-red-100 text-red-700"}`}>{x.type === "income" ? <ArrowUpLeft size={17}/> : <ArrowDownLeft size={17}/>}</span><div className="min-w-0 flex-1"><strong className="block truncate text-sm">{x.description}</strong><small className="text-xs text-muted-foreground">{x.category} · {fmtDate(x.transactionDate)}</small></div><div className={`font-bold ${x.type === "income" ? "text-emerald-700" : "text-accent"}`} dir="ltr">{x.type === "income" ? "+" : "−"}<Money value={x.amount}/></div>{isManualExpense(x) && <div className="flex gap-2"><Button variant="ghost" className="min-h-9 px-3 text-xs" onClick={() => { setEditingExpense(x); setOpen("transaction"); }} data-testid={`button-edit-wallet-${x.id}`} title="تعديل المصروف"><Edit3 size={14}/> تعديل</Button><Button variant="danger" className="min-h-9 px-3 text-xs" onClick={() => setDeleting(x)} data-testid={`button-delete-wallet-${x.id}`} title="حذف المصروف"><Trash2 size={14}/> حذف</Button></div>}</div>)}</div> : <EmptyState title="دفتر المحفظة فارغ" description="أضف حركة دخل أو مصروف للحفاظ على صورة مالية دقيقة." action={<Button onClick={() => setOpen("transaction")}>إضافة حركة</Button>}/>}</QueryState></div>{manualExpenses.length > 0 && <p className="mt-3 text-xs text-muted-foreground">تظهر أزرار التعديل والحذف للمصاريف اليدوية فقط؛ أما الدفعات ومصاريف الشحن والشراء فتُدار من صفحاتها.</p>}{flash && <Flash message={flash.message} error={flash.error}/>}<Modal open={!!open} onClose={closeForm} title={open === "adjustment" ? "تعديل رصيد المحفظة" : editingExpense ? "تعديل مصروف يدوي" : "تسجيل حركة يدوية"}><form key={editingExpense?.id ?? open ?? "closed-wallet-form"} onSubmit={submit} className="space-y-4">{open === "adjustment" ? <><div className="grid gap-4 sm:grid-cols-2"><Input label="المبلغ" name="amount" type="number" min="0.01" step="0.01" required/><Select label="اتجاه التعديل" name="direction"><option value="increase">زيادة</option><option value="decrease">نقص</option></Select><Input label="التاريخ" name="transactionDate" type="date" defaultValue={today} required/></div><Textarea label="سبب التعديل" name="reason" required/></> : <><div className="grid gap-4 sm:grid-cols-2"><Select label="نوع الحركة" name="type" defaultValue={editingExpense?.type || "expense"}><option value="income">دخل</option><option value="expense">مصروف</option></Select><Input label="المبلغ" name="amount" type="number" min="0.01" step="0.01" required defaultValue={editingExpense?.amount ?? ""}/><Input label="التصنيف" name="category" placeholder="شحن، تغليف..." required defaultValue={editingExpense?.category || ""}/><Input label="التاريخ" name="transactionDate" type="date" defaultValue={editingExpense?.transactionDate?.slice(0, 10) || today} required/></div><Input label="الوصف" name="description" required defaultValue={editingExpense?.description || ""} placeholder="وصف واضح للحركة"/>{editingExpense ? <p className="rounded-xl bg-muted p-3 text-xs text-muted-foreground">لن تتغير الملاحظات المحفوظة عند تعديل هذا المصروف.</p> : <Textarea label="ملاحظات" name="notes"/>}</>}<div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={closeForm}>إلغاء</Button><Button type="submit" disabled={busy}>{busy && <Spinner/>} {editingExpense ? "حفظ التعديلات" : "حفظ الحركة"}</Button></div></form></Modal><ConfirmModal open={!!deleting} onClose={() => setDeleting(null)} title="تأكيد حذف المصروف اليدوي" description={`سيتم حذف المصروف «${deleting?.description || ""}» وتحديث رصيد المحفظة. لا يمكن التراجع عن هذا الإجراء.`} pending={remove.isPending} onConfirm={confirmDelete}/></AppPage>;
}

export function ReportsPage() {
  const [range, setRange] = useState("month"); const params = useMemo(() => ({ range: range as "today" | "week" | "month" | "custom" }), [range]); const q = useGetReportSummary(params, { query: { queryKey: getGetReportSummaryQueryKey(params) } }); const exportParams = useMemo(() => ({ type: "profit" as const }), []); const exportQ = useExportReport(exportParams, { query: { queryKey: getExportReportQueryKey(exportParams), enabled: false } }); const [flash, setFlash] = useState("");
  const r = q.data; if (q.isLoading) return <AppPage><PageSkeleton/></AppPage>; if (q.isError || !r) return <AppPage><QueryState isError onRetry={() => q.refetch()}/></AppPage>;
  const exportCsv = async () => { await exportQ.refetch(); setFlash("تم تجهيز ملف التقرير للتنزيل"); setTimeout(() => setFlash(""), 2500); };
  return <AppPage><PageHeader eyebrow="الوضوح المالي" title="التقارير" description="اقرأ اتجاه العمل خلال فترة محددة، وصدّر السجل عندما تحتاج مشاركته." action={<Button variant="ghost" onClick={exportCsv} disabled={exportQ.isFetching} data-testid="button-export-report"><Download size={16}/> تصدير CSV</Button>}/><div className="mb-5 flex flex-wrap gap-2 rounded-2xl border border-border bg-card p-2">{[["today","اليوم"],["week","هذا الأسبوع"],["month","هذا الشهر"]].map(([v, label]) => <button key={v} onClick={() => setRange(v)} className={`rounded-xl px-4 py-2 text-xs font-bold ${range === v ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-muted"}`} data-testid={`button-report-range-${v}`}>{label}</button>)}</div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="الدخل" value={<Money value={r.income}/>} sub="كل الدفعات الداخلة" icon={ArrowUpLeft} tone="mint"/><StatCard label="المصروف" value={<Money value={r.expenses}/>} sub="كل المصروفات الخارجة" icon={ArrowDownLeft} tone="coral"/><StatCard label="الإيراد من الطلبات" value={<Money value={r.revenue}/>} sub="السعر المحصل" icon={Receipt} tone="gold"/><StatCard label="الربح" value={<Money value={r.profit}/>} sub="بعد تكلفة SHEIN والعمولة" icon={TrendingUp} tone="primary"/></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><SectionCard title="ملخص الربحية"><div className="space-y-5 p-5"><div className="h-5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-secondary" style={{width: `${r.revenue ? Math.min(100, Math.max(0, (r.profit / r.revenue) * 100)) : 0}%`}}/></div><div className="grid gap-3 sm:grid-cols-2">{[["السعر المحصل", r.revenue],["تكلفة SHEIN", r.productCosts],["العمولة", r.commission],["الربح الصافي", r.profit]].map(([label, v], i) => <div key={i} className="flex items-center justify-between rounded-xl bg-muted/60 p-3 text-sm"><span className="text-muted-foreground">{label}</span><Money value={v as number} className="font-bold"/></div>)}</div></div></SectionCard><SectionCard title="ما يحتاج متابعة"><div className="space-y-3 p-5"><div className="flex items-center justify-between rounded-xl border border-border p-4"><span className="flex items-center gap-2 text-sm"><Package size={17} className="text-accent"/> منتجات ناقصة</span><strong className="font-display text-xl">{r.missingProducts}</strong></div><div className="flex items-center justify-between rounded-xl border border-border p-4"><span className="flex items-center gap-2 text-sm"><Truck size={17} className="text-accent"/> بانتظار التسليم</span><strong className="font-display text-xl">{r.awaitingDelivery}</strong></div><div className="flex items-center justify-between rounded-xl border border-border p-4"><span className="flex items-center gap-2 text-sm"><WalletCards size={17} className="text-accent"/> أرصدة العملاء</span><Money value={r.customerBalances} className="font-bold"/></div></div></SectionCard></div>{flash && <Flash message={flash}/>}</AppPage>;
}

export function SettingsPage() {
  const q = useGetSettings({ query: { queryKey: getGetSettingsQueryKey() } }); const logs = useListAuditLogs({ limit: 20 }, { query: { queryKey: getListAuditLogsQueryKey({ limit: 20 }) } }); const save = useUpdateSettings(); const [flash, setFlash] = useState(""); const settings = q.data;
  if (q.isLoading) return <AppPage><PageSkeleton/></AppPage>; if (q.isError || !settings) return <AppPage><QueryState isError onRetry={() => q.refetch()}/></AppPage>;
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); save.mutate({ data: { businessName: String(f.get("businessName")), defaultCurrency: "ILS", initialPaymentPercent: Number(f.get("initialPaymentPercent")), defaultDeliveryFee: Number(f.get("defaultDeliveryFee")) } }, { onSuccess: () => { setFlash("تم حفظ الإعدادات"); setTimeout(() => setFlash(""), 2300); } }); };
  return <AppPage><PageHeader eyebrow="مساحة الشريكين" title="الإعدادات" description="قواعد العمل والحسابات المصرح لها بالدخول."/><div className="grid gap-5 xl:grid-cols-[1fr_1fr]"><SectionCard title="إعدادات النشاط"><form onSubmit={submit} className="space-y-5 p-5"><Input label="اسم النشاط" name="businessName" defaultValue={settings.businessName} required data-testid="input-business-name"/><div className="grid gap-4 sm:grid-cols-2"><Input label="العملة الافتراضية" name="defaultCurrency" value="ILS · شيكل" readOnly/><Input label="نسبة الدفعة الأولى (%)" name="initialPaymentPercent" type="number" min="0" max="100" defaultValue={settings.initialPaymentPercent} required/><Input label="رسوم التوصيل الافتراضية" name="defaultDeliveryFee" type="number" min="0" step="0.01" defaultValue={settings.defaultDeliveryFee} required/></div><div className="flex justify-end pt-2"><Button type="submit" disabled={save.isPending}>{save.isPending && <Spinner/>} حفظ الإعدادات</Button></div></form></SectionCard><SectionCard title="سجل التدقيق" action={<span className="text-xs text-muted-foreground">آخر ٢٠ تغييراً</span>}><QueryState isLoading={logs.isLoading} isError={logs.isError} onRetry={() => logs.refetch()}>{safeArray(logs.data).length ? <div className="divide-y divide-border/70">{safeArray(logs.data).map((x) => <div key={x.id} className="px-5 py-4"><div className="flex items-center justify-between gap-3"><strong className="text-xs">{x.action} · {x.entity}</strong><small className="text-[10px] text-muted-foreground">{fmtDate(x.createdAt)}</small></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{x.description}</p></div>)}</div> : <EmptyState title="لا يوجد سجل بعد" description="سيظهر تاريخ التغييرات هنا للحفاظ على وضوح الشراكة."/>}</QueryState></SectionCard><AccountManagement /></div>{flash && <Flash message={flash}/>}</AppPage>;
}